xql_query:
// ============================================================
// Rule: THM_cmd.exe LNK Execution
// Vendor: Windows
// Objective:
// Detect activity associated with THM_cmd.exe LNK Execution.
// Severity: SEV_040_HIGH
// Category: EXECUTION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0002 - Execution
// Technique: T1059.003 - Command and Scripting Interpreter: Windows Command Shell

// Fonte de dados: eventos do Cortex XDR
dataset = xdr_data

// Seleção de campos relevantes para análise de processos
| fields _time,                                                     // Data e hora do evento  
                agent_os_type,                                      // Sistema operacional do agente          
                agent_hostname,                                     // Nome do host
                event_type,                                         // Tipo de evento (ex: PROCESS, NETWORK, etc.)
                event_sub_type,                                     // Subtipo do evento (ex: PROCESS_START)  
                actor_process_image_name,                           // Nome do processo que iniciou a ação            
                actor_process_command_line,                         // Linha de comando do processo que originou             
                action_process_image_command_line,                  // Linha de comando do processo em execução                     
                action_process_image_path,                          // Caminho completo do processo             
                action_process_image_name                           // Nome do processo em execução             

// Filtro para capturar apenas eventos de processo do tipo "PROCESS_START"
| filter event_type = ENUM.PROCESS and event_sub_type = ENUM.PROCESS_START 

// Filtro adicional: detecção de execução do cmd.exe
// - O comando inclui "/k set"
// - O comando também faz referência a arquivos ".lnk"
// (padrão associado a execução encadeada de atalhos maliciosos)
| filter lowercase(action_process_image_name) = "cmd.exe" 
    and lowercase(action_process_image_command_line) contains "/k set"
    and lowercase(action_process_image_command_line) contains ".lnk"
